 document.title=p.title+' | The Medic Goats';
 app.innerHTML='<section class="page-heading"><div class="kicker">THE MEDIC GOATS • TEACHING WHILE LEARNING</div><p><a href="/blog" class="blog-back">← All articles</a></p><h1>'+esc(p.title)+'</h1><p>'+esc(p.category)+' • '+esc(p.date?.slice(0,10))+'</p></section><article class="medic-blog-article">'+p.html+'</article><div class="blog-share-actions"><button type="button" class="btn primary" id="shareBlogStory">Share to Instagram</button><button type="button" class="btn" id="shareBlogLink">Share Article</button></div><p id="blogShareStatus" class="blog-share-status" role="status" aria-live="polite"></p><section id="medicKnowledgeCheck" class="medic-knowledge-check"></section><section class="blog-bottom"><a href="/blog" class="btn primary">← Back to Blog</a></section>';
